    "desc": "Check unstaged changes or whether an existing or new branch name is available",
    "body": "version: v1alpha1\ntitle: Branch check\ndescription: Check unstaged changes or whether an existing or new branch name is available\ninputs:\n  mode:\n    type: choice\n    options: [status, branch]\n    default: status\n  branch:\n    type: choice\n    options: [main]\n    allow_custom: true\n    min_length: 1\n    when: '{{inputs.mode}} == \"branch\"'\nsteps:\n  - id: changes\n    run: [git, diff, --quiet]\n    success_codes: [0, 1]\n\n  - herdr: notification.show\n    params:\n      title: working tree clean\n      body: git diff found no changes\n      sound: done\n    when:\n      - '{{inputs.mode}} == \"status\"'\n      - '{{steps.changes.exit_code}} == \"0\"'\n\n  - herdr: notification.show\n    params:\n      title: working tree changed\n      body: git diff found changes\n      sound: request\n    when:\n      - '{{inputs.mode}} == \"status\"'\n      - '{{steps.changes.exit_code}} != \"0\"'\n\n  - id: branch_exists\n    run: [git, show-ref, --verify, --quiet, \"refs/heads/{{inputs.branch}}\"]\n    success_codes: [0, 1]\n    when: '{{inputs.mode}} == \"branch\"'\n\n  - herdr: notification.show\n    params:\n      title: branch exists\n      body: \"{{inputs.branch}} already exists\"\n      sound: request\n    when:\n      - '{{inputs.mode}} == \"branch\"'\n      - '{{steps.branch_exists.exit_code}} == \"0\"'\n\n  - herdr: notification.show\n    params:\n      title: branch available\n      body: \"{{inputs.branch}} does not exist\"\n      sound: done\n    when:\n      - '{{inputs.mode}} == \"branch\"'\n      - '{{steps.branch_exists.exit_code}} != \"0\"'\n",
    "payload": ""
