  {
    "name": "worktree",
    "desc": "create, open or delete a git worktree, with an agent in its work pane",
    "body": "version: v1alpha1\ntitle: Worktrees\ndescription: create, open or delete a git worktree, with an agent in its work pane\non_failure:\n  herdr: notification.show\n  params:\n    title: Worktrees workflow failed\n    body: \"{{context.error.message}}\"\n    sound: request\ninputs:\n  mode:\n    type: choice\n    description: what to do with a worktree\n    options:\n      - create\n      - open\n      - delete\n    default: create\n  # reference to check out from: local branches and remote-tracking branches, newest first\n  ref:\n    type: choice\n    description: reference the new branch starts from\n    when: '{{inputs.mode}} == \"create\"'\n    options:\n      run:\n        [\n          sh,\n          -c,\n          \"git for-each-ref --exclude='refs/remotes/*/HEAD' --sort=-committerdate --format='%(refname:short)' refs/heads refs/remotes\",\n        ]\n  # new branch to create at that reference; an existing branch name is checked out as-is instead\n  branch:\n    type: text\n    description: worktree branch to create, or an existing branch to check out\n    when: '{{inputs.mode}} == \"create\"'\n    min_length: 1\n  worktree:\n    type: choice\n    description: which existing worktree\n    when: '{{inputs.mode}} != \"create\"'\n    options:\n      run:\n        [\n          sh,\n          -c,\n          \"set -eu; list=$(herdr worktree list --cwd . --json); printf %s \\\"$list\\\" | jq -r '.result.worktrees[]? | select(.is_linked_worktree) | .branch'\",\n        ]\n  scope:\n    type: choice\n    description: delete the checkout only, or its branch as well\n    when: '{{inputs.mode}} == \"delete\"'\n    options:\n      - worktree-only\n      - worktree-and-branch\n    default: worktree-only\nsteps:\n  # cmd /c on Windows, sh -c elsewhere - this text is valid in both\n  - when: '{{context.platform}} == \"windows\"'\n    run: |\n      echo This workflow needs a POSIX shell with git, jq and herdr on PATH - run herdr from WSL or Git Bash. 1>&2\n      exit 1\n\n  - run: |\n      set -eu\n      missing=\n      for c in git jq herdr; do\n        command -v \"$c\" >/dev/null 2>&1 || missing=\"$missing $c\"\n      done\n      if [ -n \"$missing\" ]; then\n        echo \"missing required tools:$missing\" >&2\n        exit 1\n      fi\n      git rev-parse --git-dir >/dev/null 2>&1 || {\n        echo \"not a git repository - run this workflow from a checkout\" >&2\n        exit 1\n      }\n\n  # herdr 0.8.0 worktree actions take exactly one of workspace_id or cwd;\n  # workspace_id only resolves for worktree-backed workspaces, so pass the repo root instead\n  - id: repo\n    run: printf %s \"$(git rev-parse --show-toplevel)\"\n\n  - id: created\n    when: '{{inputs.mode}} == \"create\"'\n    herdr: worktree.create\n    params:\n      cwd: \"{{steps.repo.stdout}}\"\n      branch: \"{{inputs.branch}}\"\n      base: \"{{inputs.ref}}\"\n      label: \"{{inputs.branch}}\"\n      focus: true\n\n  - workflow: worktree-layout\n    when: '{{inputs.mode}} == \"create\"'\n    inputs:\n      tab_id: \"{{steps.created.tab.tab_id}}\"\n      root_pane_id: \"{{steps.created.root_pane.pane_id}}\"\n\n  - id: opened\n    when:\n      - '{{inputs.mode}} != \"create\"'\n      - '{{inputs.mode}} == \"open\"'\n    herdr: worktree.open\n    params:\n      cwd: \"{{steps.repo.stdout}}\"\n      branch: \"{{inputs.worktree}}\"\n      label: \"{{inputs.worktree}}\"\n      focus: true\n\n  - workflow: worktree-layout\n    when:\n      - '{{inputs.mode}} != \"create\"'\n      - '{{inputs.mode}} == \"open\"'\n    inputs:\n      tab_id: \"{{steps.opened.tab.tab_id}}\"\n      root_pane_id: \"{{steps.opened.root_pane.pane_id}}\"\n\n  - id: deleted\n    when:\n      - '{{inputs.mode}} != \"create\"'\n      - '{{inputs.mode}} == \"delete\"'\n    env:\n      WT: \"{{inputs.worktree}}\"\n      SCOPE: \"{{inputs.scope}}\"\n    run: |\n      set -eu\n      list=$(herdr worktree list --cwd . --json)\n      root=$(printf %s \"$list\" | jq -r '.result.source.repo_root')\n      entry=$(printf %s \"$list\" | jq -c --arg b \"$WT\" \\\n        'first(.result.worktrees[] | select(.is_linked_worktree and .branch == $b))')\n      if [ -z \"$entry\" ] || [ \"$entry\" = null ]; then\n        echo \"no worktree checkout for branch $WT\" >&2\n        exit 1\n      fi\n      path=$(printf %s \"$entry\" | jq -r '.path')\n      ws=$(printf %s \"$entry\" | jq -r '.open_workspace_id // empty')\n\n      if [ -n \"$ws\" ]; then\n        herdr worktree remove --workspace \"$ws\"\n      else\n        git -C \"$root\" worktree remove \"$path\"\n      fi\n\n      if [ \"$SCOPE\" = worktree-only ]; then\n        printf %s \"removed the $WT worktree; branch kept\"\n      elif git -C \"$root\" branch -d \"$WT\" >/dev/null 2>&1; then\n        printf %s \"removed the $WT worktree and its branch\"\n      else\n        printf %s \"removed the $WT worktree; branch kept, it is not merged (git branch -D $WT)\"\n      fi\n\n  - when:\n      - '{{inputs.mode}} != \"create\"'\n      - '{{inputs.mode}} == \"delete\"'\n      - \"{{steps.deleted.stdout}}\"\n    herdr: notification.show\n    params:\n      title: Worktree deleted\n      body: \"{{steps.deleted.stdout}}\"\n      sound: done\n",
    "payload": ""
  }
